function updateHud(){for(const [id,val] of [['health',player.hp],['hunger',player.hunger],['thirst',player.thirst],['stamina',player.stamina]])document.getElementById(id).style.width=Math.max(0,val)+'%';document.getElementById('healthN').textContent=Math.ceil(player.hp);document.getElementById('hungerN').textContent=Math.ceil(player.hunger);document.getElementById('thirstN').textContent=Math.ceil(player.thirst);document.getElementById('staminaN').textContent=Math.ceil(player.stamina);document.getElementById('ammo').textContent=player.ammo;document.getElementById('meds').textContent=player.meds}
function finish(survived){if(ended)return;ended=true;active=false;document.getElementById('end').classList.remove('hidden');document.getElementById('endEyebrow').textContent=survived?'EXTRACTION CONFIRMED':'THE CITY REMEMBERS';document.getElementById('endTitle').innerHTML=survived?'YOU <span>MADE IT</span>':'YOU <span>FELL</span>';document.getElementById('endSub').textContent=survived?'The flare burns through the morning fog.':'The quiet takes another one.';document.getElementById('endStory').textContent=`Survived ${Math.floor(gameElapsed/60)} minutes · ${kills} infected put down · ${Math.max(0,loot.filter(l=>l.taken).length)} caches scavenged. ${survived?'Someone will remember.':'The city keeps what it is given.'}`}
function draw(){ctx.save();ctx.translate((Math.random()-.5)*shake,(Math.random()-.5)*shake);ctx.fillStyle='#41443b';ctx.fillRect(0,0,W,H);ctx.save();ctx.translate(-camera.x,-camera.y);
// Asphalt grid and patched road markings
ctx.fillStyle='#46483f';ctx.fillRect(0,0,world.w,world.h);for(let y=0;y<world.h;y+=310){ctx.fillStyle='#3d4039';ctx.fillRect(0,y+210,world.w,78);ctx.fillStyle='#777666';for(let x=15;x<world.w;x+=120)ctx.fillRect(x,y+247,48,2)}for(let x=0;x<world.w;x+=360){ctx.fillStyle='#3d4039';ctx.fillRect(x+280,0,68,world.h);ctx.fillStyle='#747466';for(let y=20;y<world.h;y+=120)ctx.fillRect(x+312,y,2,46)}
// Pavement cracks / weed growth
for(let i=0;i<180;i++){let x=(i*173+37)%world.w,y=(i*271+63)%world.h;ctx.strokeStyle=i%3?'#333831':'#737264';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x,y);ctx.lineTo(x+rr(-12,12),y+rr(5,22));ctx.lineTo(x+rr(-24,17),y+rr(20,35));ctx.stroke()}
for(const d of decor){if(d.type==='tree'){ctx.fillStyle='#30372e';ctx.beginPath();ctx.arc(d.x,d.y,14*d.s,0,Math.PI*2);ctx.fill();ctx.fillStyle='#485241';ctx.beginPath();ctx.arc(d.x-5,d.y-5,10*d.s,0,Math.PI*2);ctx.fill()}else if(d.type==='car'){ctx.save();ctx.translate(d.x,d.y);ctx.rotate((d.s-1)*.7);ctx.fillStyle='#292d29';ctx.fillRect(-21,-10,42,22);ctx.fillStyle=['#62564b','#4a5550','#777260'][Math.floor((d.x+d.y)%3)];ctx.fillRect(-16,-8,32,16);ctx.fillStyle='#252b28';ctx.fillRect(-11,-7,11,14);ctx.restore()}else if(d.type==='rubble'){ctx.fillStyle='#686355';for(let k=0;k<4;k++){ctx.save();ctx.translate(d.x+k*7,d.y+k%2*4);ctx.rotate(k*.47);ctx.fillRect(-5,-4,12,8);ctx.restore()}}else if(d.type==='grass'){ctx.strokeStyle='#6b7654';ctx.lineWidth=2;for(let k=0;k<3;k++){ctx.beginPath();ctx.moveTo(d.x+k*4,d.y);ctx.lineTo(d.x+k*4-4,d.y-10*d.s);ctx.stroke()}}else{ctx.fillStyle='#30342f';ctx.fillRect(d.x-2,d.y-20,4,40);ctx.fillStyle='#b8a36e';ctx.beginPath();ctx.arc(d.x,d.y-20,4,0,Math.PI*2);ctx.fill()}}
